using System;
using System.Globalization;
using System.Reflection;
using System.Runtime.InteropServices;
using MelloCharts;

public static class ExcelIntegrationTests {
  static int passed,failed;
  static void Is(bool value,string message){if(!value)throw new Exception(message);}
  static void Test(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+(ex.InnerException??ex).Message);}}
  static ChartDocument Capture(object app,string type){Type bridge=typeof(ChartCore).Assembly.GetType("MelloCharts.ExcelBridge");if(bridge==null)throw new Exception("ExcelBridge ausente");return (ChartDocument)bridge.GetMethod("CaptureSelection").Invoke(null,new[]{app,(object)type});}
  static void Reject(Action action){try{action();}catch(Exception e){Exception error=e is TargetInvocationException?e.InnerException:e;if(error is ArgumentException||error is InvalidOperationException)return;throw;}throw new Exception("Seleção inválida foi aceita");}
  static object Link(ChartDocument d){FieldInfo field=typeof(ChartDocument).GetField("excelLink");Is(field!=null,"Vínculo Excel ausente");return field.GetValue(d);}
  static string Part(object link,string field){return (string)link.GetType().GetField(field).GetValue(link);}
  [STAThread]public static int Main(){
    Test("Excel capture identifies real source instead of fictional example",delegate{ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{"A",10.0}});ChartDocument doc=Capture(new ExcelApplication(range),"pie");Is(doc.source.StartsWith("Excel ·")&&!doc.source.Contains("fict"),"Dados reais com fonte fictícia");});
    Test("Excel numeric values remain exact across decimal cultures",delegate{CultureInfo previous=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("pt-BR");ExcelRange range=new ExcelRange(new object[,]{{"categoria","realizado","projetado","baseline"},{"A",1.25,2.5,4.75}});ChartDocument doc=Capture(new ExcelApplication(range),"columns");Is(doc.rows.Count==1&&doc.rows[0].actual==1.25&&doc.rows[0].forecast==2.5&&doc.rows[0].baseline==4.75,"Decimais alterados");}finally{CultureInfo.CurrentCulture=previous;}});
    Test("Excel formula results use cached values and category display text",delegate{ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{45678.0,12.75}});range.CategoryText="jan/2025";ChartDocument doc=Capture(new ExcelApplication(range),"pie");Is(doc.rows[0].label=="jan/2025"&&doc.rows[0].value==12.75,"Valor calculado ou categoria perdidos");});
    Test("Excel category aliases preserve displayed dates",delegate{foreach(string header in new[]{"projeto","pep","etapa"}){ExcelRange range=new ExcelRange(new object[,]{{header,"valor"},{45678.0,12.75}});range.CategoryText="jan/2025";ChartDocument doc=Capture(new ExcelApplication(range),"pie");Is(doc.rows[0].label=="jan/2025","Categoria exibida perdida para "+header);}ExcelRange gantt=new ExcelRange(new object[,]{{"atividade","inicio","fim","progresso"},{45678.0,"2026-10-01","2026-10-03",50.0}});gantt.CategoryText="jan/2025";Is(Capture(new ExcelApplication(gantt),"gantt").rows[0].label=="jan/2025","Atividade exibida perdida");});
    Test("Excel Gantt converts workbook 1904 serials to calendar dates",delegate{ExcelRange range=new ExcelRange(new object[,]{{"atividade","inicio","fim","progresso"},{"A",0.0,1.0,50.0}});range.Worksheet.Parent.Date1904=true;ChartDocument doc=Capture(new ExcelApplication(range),"gantt");Is(doc.rows[0].startDate=="1904-01-01"&&doc.rows[0].endDate=="1904-01-02","Sistema1904 ignorado");});
    Test("Excel Gantt converts formatted percentages but keeps plain decimals",delegate{foreach(string format in new[]{"0%","0.0%","0.00","0\\%","0\"%\""}){ExcelRange range=new ExcelRange(new object[,]{{"atividade","inicio","fim","progresso"},{"A","2026-10-01","2026-10-03",0.5}});range.Formats[1,3]=format;ChartDocument doc=Capture(new ExcelApplication(range),"gantt");double expected=format=="0%"||format=="0.0%"?50:0.5;Is(doc.rows[0].progress==expected,"Progresso incorreto para "+format);}});
    Test("Excel source link survives project and chart metadata roundtrip",delegate{ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{"A",10.0}});ChartDocument d=Capture(new ExcelApplication(range),"pie");object link=Link(Metadata.Decode(Metadata.Encode(d)));Is(link!=null&&Part(link,"path")==@"C:\Reports\Budget.xlsx"&&Part(link,"sheet")=="Orçamento"&&Part(link,"range")=="$A$1:$B$2","Origem Excel não preservada");});
    Test("unsaved workbook and unsupported extension do not create a source link",delegate{foreach(string path in new[]{"",@"C:\Reports\Budget.xlsm"}){ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{"A",10.0}});range.Worksheet.Parent.Path=path==""?"":@"C:\Reports";range.Worksheet.Parent.FullName=path;Is(Link(Capture(new ExcelApplication(range),"pie"))==null,"Vínculo sem XLSX salvo");}});
    Test("noncontiguous selection is rejected before reading values",delegate{ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{"A",10.0}});range.Areas.Count=2;range.ForbidValueRead=true;Reject(delegate{Capture(new ExcelApplication(range),"pie");});Is(!range.ValuesRead,"Leu dados de seleção inválida");});
    Test("oversized selection is rejected before reading values",delegate{ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{"A",10.0}});range.Rows.Count=1048576;range.ForbidValueRead=true;Reject(delegate{Capture(new ExcelApplication(range),"pie");});Is(!range.ValuesRead,"Leu coluna inteira");});
    Test("Excel captures the full supported scatter selection and rejects the next row",delegate{object[,] data=new object[81,3];data[0,0]="categoria";data[0,1]="x";data[0,2]="y";for(int i=1;i<81;i++){data[i,0]="Ponto "+i;data[i,1]=i*.25;data[i,2]=i*.5;}ExcelRange range=new ExcelRange(data);Is(Capture(new ExcelApplication(range),"scatter").rows.Count==80,"Dispersão truncada");range.Rows.Count=82;range.ForbidValueRead=true;range.ValuesRead=false;Reject(delegate{Capture(new ExcelApplication(range),"scatter");});Is(!range.ValuesRead,"Leu dispersão acima do limite");});
    Test("classic charts reject a thirteenth category before reading",delegate{ExcelRange range=new ExcelRange(new object[,]{{"categoria","valor"},{"A",10.0}});range.Rows.Count=14;range.ForbidValueRead=true;Reject(delegate{Capture(new ExcelApplication(range),"pie");});Is(!range.ValuesRead,"Limite clássico ignorado");});
    Test("selected shapes and missing headers are rejected",delegate{Reject(delegate{Capture(new ExcelApplication(new object()),"pie");});Reject(delegate{Capture(new ExcelApplication(new ExcelRange(new object[,]{{"A",10.0},{"B",20.0}})),"pie");});});
    Test("Excel errors never become numeric chart values",delegate{Reject(delegate{Capture(new ExcelApplication(new ExcelRange(new object[,]{{"categoria","valor"},{"A",new ErrorWrapper(2007)}})),"pie");});});
    Test("Excel ribbon exposes import and gallery callbacks",delegate{Type type=typeof(ChartCore).Assembly.GetType("MelloCharts.ExcelConnect");Is(type!=null,"Suplemento Excel ausente");object addin=Activator.CreateInstance(type);string xml=(string)type.GetMethod("GetCustomUI").Invoke(addin,new object[]{"Microsoft.Excel.Workbook"});Is(xml.Contains("Criar da seleção")&&xml.Contains("onAction='NewFromSelection'")&&xml.Contains("onAction='NewGallery'"),"Comandos Excel ausentes");});
    Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1;
  }
}
public sealed class ExcelApplication {public object Selection {get;set;}public ExcelApplication(object selection){Selection=selection;}}
public sealed class ExcelCount {public int Count {get;set;}}
public sealed class ExcelWorkbook {public bool Date1904 {get;set;}public string Path {get;set;}public string FullName {get;set;}public ExcelWorkbook(){Path=@"C:\Reports";FullName=@"C:\Reports\Budget.xlsx";}}
public sealed class ExcelWorksheet {public string Name {get;set;}public ExcelWorkbook Parent {get;set;}public ExcelWorksheet(){Name="Orçamento";Parent=new ExcelWorkbook();}}
public sealed class ExcelCell {public string Text {get;set;}public string NumberFormat {get;set;}}
public sealed class ExcelCells {readonly ExcelRange owner;public ExcelCells(ExcelRange range){owner=range;}public ExcelCell this[int row,int column]{get{return new ExcelCell{Text=row>1&&column==1&&owner.CategoryText!=null?owner.CategoryText:Convert.ToString(owner.Values[row-1,column-1],CultureInfo.InvariantCulture),NumberFormat=owner.Formats[row-1,column-1]??"General"};}}}
public sealed class ExcelRange {
  public object[,] Values;public string[,] Formats;public bool ValuesRead,ForbidValueRead;public string CategoryText;
  public ExcelCount Areas {get;set;}public ExcelCount Rows {get;set;}public ExcelCount Columns {get;set;}public ExcelWorksheet Worksheet {get;set;}public ExcelCells Cells {get;set;}
  public object Value2 {get{ValuesRead=true;if(ForbidValueRead)throw new Exception("Não deveria ler Value2");return Values;}}
  public ExcelRange(object[,] values){Values=values;Formats=new string[values.GetLength(0),values.GetLength(1)];Areas=new ExcelCount{Count=1};Rows=new ExcelCount{Count=values.GetLength(0)};Columns=new ExcelCount{Count=values.GetLength(1)};Worksheet=new ExcelWorksheet();Cells=new ExcelCells(this);}
  public string Address {get{return "$A$1:$B$2";}}
}
